// Asks the person to confirm an action, and for the reason the action
// sends, in a dialog; the browser's own confirm cannot take a reason.

/** Resolves to the reason typed, "" when the action takes none, or null
    when the person cancels. reason, when the action sends one, gives its
    label and its length. */
export function ask(question, reason) {
  if (!question && !reason) {
    return Promise.resolve("");
  }
  const dialog = document.createElement("dialog");
  const form = document.createElement("form");
  form.method = "dialog";
  if (question) {
    const text = document.createElement("p");
    text.textContent = question;
    form.append(text);
  }
  let field;
  if (reason) {
    const label = document.createElement("label");
    label.textContent = reason.label;
    field = document.createElement("textarea");
    field.required = true;
    if (reason.minLength !== undefined) {
      field.minLength = reason.minLength;
    }
    if (reason.maxLength !== undefined) {
      field.maxLength = reason.maxLength;
    }
    label.append(field);
    form.append(label);
  }
  const cancel = document.createElement("button");
  cancel.value = "cancel";
  cancel.formNoValidate = true;
  cancel.textContent = "Cancel";
  const confirm = document.createElement("button");
  confirm.value = "confirm";
  confirm.textContent = "Confirm";
  form.append(cancel, confirm);
  dialog.append(form);
  document.body.append(dialog);
  dialog.showModal();
  return new Promise((resolve) => {
    dialog.addEventListener("close", () => {
      dialog.remove();
      resolve(dialog.returnValue === "confirm" ? (field?.value.trim() ?? "") : null);
    });
  });
}
